class Sonde(Scene):
    def construct(self):
        titlle = Text("Ballon sonde").scale(1.5).to_edge(UP)
        
        ballon = Ellipse(width=3, height=3.5, color=BLUE, fill_opacity=0.7)
        box = Rectangle(height=1, width=1.2, color=WHITE, fill_opacity=0.7).next_to(ballon, DOWN, buff=1)
        cord = Line(start=box.get_top(), end=ballon.get_bottom(), color=WHITE)
        ballonGroup = VGroup(ballon, box, cord)
        stateVector = MathTex(r"X = \begin{bmatrix} alt \end{bmatrix}").scale(1.2).shift(RIGHT*2+DOWN)
        stateVector[0][0].set_color(BLUE)
        
        self.play(Write(titlle))
        self.play(Create(ballonGroup))
        self.wait(2)
        self.play(ballonGroup.animate.shift(LEFT*5), Write(stateVector))

        GPSTxt = Text("GPS").scale(0.5).next_to(box, RIGHT, buff=2).shift(UP)
        GPSCross = Cross(GPSTxt)
        GPSArrow = Arrow(GPSTxt,box)
        
        ThermTxt = Text("thermomètre").scale(0.5).next_to(box, RIGHT, buff=2)
        ThermArrow = Arrow(ThermTxt, box)
        
        self.play(Create(GPSTxt), Create(GPSArrow))
        self.wait(2)
        self.play(FadeIn(GPSCross))
        self.wait(2)
        self.play(Create(ThermTxt), Create(ThermArrow), FadeOut(GPSArrow), FadeOut(GPSCross), FadeOut(GPSTxt))
        self.wait(5)
        
        self.play(FadeOut(ThermArrow), FadeOut(ThermTxt))
        
        
        
        
        axes = Axes(
            x_range=[min(temp)-20, max(temp)+20, 10],
            y_range=[0, max(altitude)+1000, 5000],
            x_length=6,
            y_length=3,
        ).to_corner(DR).shift(LEFT*2)
        axes_labels = axes.get_axis_labels(x_label="Temperature", y_label="Altitude")
        
        graph_temp_vs_altitude = axes.plot_line_graph(
            x_values = temp, 
            y_values = altitude, 
            line_color=RED,
            add_vertex_dots=False
            )
        
        self.play(Create(axes), Create(axes_labels), Create(graph_temp_vs_altitude), stateVector.animate.shift(UP*2))
        
        self.wait(3)
        
        # y->température(altitude)
        measureFunc = MathTex(r"Y -> temp(alt)").scale(1.2).next_to(stateVector, DOWN)
        measureFunc[0][0].set_color(RED)
        self.play(Write(measureFunc), FadeOut(graph_temp_vs_altitude, axes, axes_labels))
        
        self.wait(3)
        prediction = MathTex(r"f(X, U) = \begin{bmatrix} alt + \Delta t*v \end{bmatrix}").scale(1.2).next_to(measureFunc, DOWN)
        prediction[0][2].set_color(BLUE)
        prediction[0][4].set_color(ORANGE)
        
        command = MathTex(r"U = \begin{bmatrix} v \end{bmatrix}").scale(1.2).next_to(prediction, DOWN)
        command[0][0].set_color(ORANGE)
        
        speedArrow = Arrow(ballon.get_center(), ballon.get_center()+UP*3, color=ORANGE)
        ballonGroup = VGroup(ballon, box, cord, speedArrow)
        self.play(Write(prediction), Write(command), Create(speedArrow))
        self.wait(3)
        
        self.play(ballonGroup.animate.shift(UP*10).set_opacity(0), run_time=2)
        self.play(FadeOut(stateVector), FadeOut(measureFunc), FadeOut(prediction), FadeOut(command))

        
        newaxes = Axes(
            x_range=[min(time)-20, max(time)+20, 500],
            y_range=[min(measurments)-10, max(measurments)+20, 10],
            x_length=10,
            y_length=5,
        ).shift(DOWN)
        
        newaxes_labels = newaxes.get_axis_labels(x_label="Time", y_label="temperature")
        
        graph_temp_vs_time = newaxes.plot_line_graph(
            x_values = time, 
            y_values = measurments, 
            line_color=RED,
            add_vertex_dots=False
            )
        # label 
        label = Text("Y").scale(1).next_to(newaxes_labels, UP).set_color(RED).shift(DOWN*1.5)
        self.play(Create(newaxes), Write(newaxes_labels), Create(graph_temp_vs_time), Write(label))
        self.wait(3)
        
        ekf_alt_vs_time_axes = Axes(
            x_range=[min(time)-20, max(time)+20, 500],
            y_range=[min(EkfAlt)-10, max(EkfAlt)+20, 5000],
            x_length=10,
            y_length=5,
        ).shift(DOWN)
        
        ekf_alt_vs_time_axes_labels = ekf_alt_vs_time_axes.get_axis_labels(x_label="Time", y_label="Altitude")
        
        graph_ekf_alt_vs_time = ekf_alt_vs_time_axes.plot_line_graph(
            x_values = time, 
            y_values = EkfAlt, 
            line_color=BLUE,
            add_vertex_dots=False
            )
        
        graph_upper = ekf_alt_vs_time_axes.plot(
        lambda x: np.interp(x, time, EkfAlt_plus_3sigma),  # Interpolation des valeurs
            x_range=[min(time), max(time)],
            color=BLUE,
            )
        graph_lower = ekf_alt_vs_time_axes.plot(
            lambda x: np.interp(x, time, EkfAlt_minus_3sigma),  # Interpolation des valeurs
            x_range=[min(time), max(time)],
            color=BLUE,
            )

        # Création de la zone remplie entre les deux courbes
        filled_region = ekf_alt_vs_time_axes.get_area(graph_lower, x_range = [min(time), max(time)], bounded_graph=graph_upper, color=BLUE, opacity=0.5, stroke_width=0)
        label2 = MathTex(r"\hat{X}").scale(1).next_to(ekf_alt_vs_time_axes_labels, UP).set_color(BLUE).shift(DOWN*1.5)
        self.play(ReplacementTransform(newaxes, ekf_alt_vs_time_axes),
                  ReplacementTransform(newaxes_labels, ekf_alt_vs_time_axes_labels),
                  FadeOut(graph_temp_vs_time),
                  FadeIn(graph_ekf_alt_vs_time),
                  FadeIn(filled_region),
                  Transform(label, label2)
                  )
        
        TrueAltGraph = ekf_alt_vs_time_axes.plot_line_graph(
            x_values = time, 
            y_values = TrueAlt, 
            line_color=WHITE,
            add_vertex_dots=False
            )
        
        self.wait(3)
        self.play(Create(TrueAltGraph))
        
        

if __name__ == "__main__":
    # Export en MP4
    config.format = "mp4"
    Sonde().render()  # Rend en vidéo MP4
